import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import { TpmjsClient, resetTpmjsClient, getTpmjsClient } from '../../src/tools/tpmjs_client.js';

// Mock the logger to suppress output during tests
vi.mock('../../src/utils/logger.js', () => ({
  logger: {
    info: vi.fn(),
    warn: vi.fn(),
    error: vi.fn(),
    debug: vi.fn(),
  },
}));

describe('TpmjsClient', () => {
  let client: TpmjsClient;
  let fetchSpy: ReturnType<typeof vi.spyOn>;

  beforeEach(() => {
    client = new TpmjsClient('https://test-registry.example.com');
    fetchSpy = vi.spyOn(globalThis, 'fetch');
  });

  afterEach(() => {
    fetchSpy.mockRestore();
    resetTpmjsClient();
  });

  describe('constructor', () => {
    it('strips trailing slashes from registry URL', () => {
      const c = new TpmjsClient('https://example.com///');
      // Verify by searching — the URL is private, so we test via a ping call
      fetchSpy.mockResolvedValue(new Response('', { status: 200 }));
      void c.ping();
      expect(fetchSpy).toHaveBeenCalledWith(
        'https://example.com/api/v1/health',
        expect.any(Object),
      );
    });

    it('uses default registry URL when none provided', () => {
      const c = new TpmjsClient();
      fetchSpy.mockResolvedValue(new Response('', { status: 200 }));
      void c.ping();
      expect(fetchSpy).toHaveBeenCalledWith(
        'https://registry.tpmjs.com/api/v1/health',
        expect.any(Object),
      );
    });
  });

  describe('search', () => {
    it('returns results on success', async () => {
      const mockResults = [
        { name: '@tpmjs/test-tool', description: 'A test tool', version: '1.0.0' },
      ];
      fetchSpy.mockResolvedValue(
        new Response(JSON.stringify({ results: mockResults, total: 1 }), { status: 200 }),
      );

      const results = await client.search('test');
      expect(results).toEqual(mockResults);
      expect(fetchSpy).toHaveBeenCalledWith(
        'https://test-registry.example.com/api/v1/search?q=test&limit=20',
        expect.objectContaining({
          headers: expect.objectContaining({ 'Accept': 'application/json' }),
        }),
      );
    });

    it('respects custom limit', async () => {
      fetchSpy.mockResolvedValue(
        new Response(JSON.stringify({ results: [], total: 0 }), { status: 200 }),
      );

      await client.search('query', 5);
      expect(fetchSpy).toHaveBeenCalledWith(
        expect.stringContaining('limit=5'),
        expect.any(Object),
      );
    });

    it('returns empty array on HTTP error', async () => {
      fetchSpy.mockResolvedValue(new Response('', { status: 500 }));
      const results = await client.search('test');
      expect(results).toEqual([]);
    });

    it('returns empty array on network error', async () => {
      fetchSpy.mockRejectedValue(new Error('Network error'));
      const results = await client.search('test');
      expect(results).toEqual([]);
    });

    it('returns empty array when results field is missing', async () => {
      fetchSpy.mockResolvedValue(
        new Response(JSON.stringify({}), { status: 200 }),
      );
      const results = await client.search('test');
      expect(results).toEqual([]);
    });
  });

  describe('getManifest', () => {
    const mockManifest = {
      name: '@tpmjs/test-tool',
      version: '1.0.0',
      description: 'A test tool',
      tools: [{ name: 'test_action', description: 'Do a test', parameters: [] }],
      mcp: { transport: 'stdio' as const, command: 'node', args: ['server.js'] },
    };

    it('returns manifest on success', async () => {
      fetchSpy.mockResolvedValue(
        new Response(JSON.stringify(mockManifest), { status: 200 }),
      );

      const result = await client.getManifest('@tpmjs/test-tool');
      expect(result).toEqual(mockManifest);
      expect(fetchSpy).toHaveBeenCalledWith(
        'https://test-registry.example.com/api/v1/packages/%40tpmjs%2Ftest-tool',
        expect.any(Object),
      );
    });

    it('returns null on 404', async () => {
      fetchSpy.mockResolvedValue(new Response('', { status: 404 }));
      const result = await client.getManifest('nonexistent');
      expect(result).toBeNull();
    });

    it('returns null on non-OK status', async () => {
      fetchSpy.mockResolvedValue(new Response('', { status: 503 }));
      const result = await client.getManifest('@tpmjs/test-tool');
      expect(result).toBeNull();
    });

    it('returns null on network error', async () => {
      fetchSpy.mockRejectedValue(new Error('Connection refused'));
      const result = await client.getManifest('@tpmjs/test-tool');
      expect(result).toBeNull();
    });
  });

  describe('getManifests', () => {
    it('fetches multiple manifests in parallel', async () => {
      const manifest1 = { name: 'pkg1', version: '1.0.0', description: 'P1', tools: [] };
      const manifest2 = { name: 'pkg2', version: '1.0.0', description: 'P2', tools: [] };

      fetchSpy
        .mockResolvedValueOnce(new Response(JSON.stringify(manifest1), { status: 200 }))
        .mockResolvedValueOnce(new Response(JSON.stringify(manifest2), { status: 200 }));

      const results = await client.getManifests(['pkg1', 'pkg2']);
      expect(results.size).toBe(2);
      expect(results.get('pkg1')).toEqual(manifest1);
      expect(results.get('pkg2')).toEqual(manifest2);
    });

    it('skips packages that return null', async () => {
      const manifest1 = { name: 'pkg1', version: '1.0.0', description: 'P1', tools: [] };

      fetchSpy
        .mockResolvedValueOnce(new Response(JSON.stringify(manifest1), { status: 200 }))
        .mockResolvedValueOnce(new Response('', { status: 404 }));

      const results = await client.getManifests(['pkg1', 'nonexistent']);
      expect(results.size).toBe(1);
      expect(results.has('pkg1')).toBe(true);
    });

    it('returns empty map for empty input', async () => {
      const results = await client.getManifests([]);
      expect(results.size).toBe(0);
    });
  });

  describe('ping', () => {
    it('returns true when registry is reachable', async () => {
      fetchSpy.mockResolvedValue(new Response('', { status: 200 }));
      expect(await client.ping()).toBe(true);
    });

    it('returns false on non-OK response', async () => {
      fetchSpy.mockResolvedValue(new Response('', { status: 503 }));
      expect(await client.ping()).toBe(false);
    });

    it('returns false on network error', async () => {
      fetchSpy.mockRejectedValue(new Error('Network error'));
      expect(await client.ping()).toBe(false);
    });
  });

  describe('singleton', () => {
    it('returns the same instance on repeated calls', () => {
      const a = getTpmjsClient('https://a.example.com');
      const b = getTpmjsClient('https://b.example.com');
      expect(a).toBe(b);
    });

    it('returns a new instance after reset', () => {
      const a = getTpmjsClient('https://a.example.com');
      resetTpmjsClient();
      const b = getTpmjsClient('https://b.example.com');
      expect(a).not.toBe(b);
    });
  });
});

