import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import {
  loadFetchConfig,
  resolveTools,
  resolveSinglePackage,
  getCachedManifest,
  clearManifestCache,
} from '../../src/tools/tpmjs_loader.js';
import { resetTpmjsClient } from '../../src/tools/tpmjs_client.js';
import type { TpmjsManifest } from '../../src/tools/tpmjs_client.js';
import fs from 'fs/promises';
import path from 'path';
import os from 'os';

// Mock logger
vi.mock('../../src/utils/logger.js', () => ({
  logger: {
    info: vi.fn(),
    warn: vi.fn(),
    error: vi.fn(),
    debug: vi.fn(),
  },
}));

// Mock child_process exec to prevent real npm installs
vi.mock('child_process', () => ({
  exec: vi.fn((_cmd: string, _opts: unknown, cb: (err: Error | null, result: { stdout: string; stderr: string }) => void) => {
    cb(null, { stdout: '', stderr: '' });
  }),
}));

describe('tpmjs_loader', () => {
  let fetchSpy: ReturnType<typeof vi.spyOn>;

  beforeEach(() => {
    fetchSpy = vi.spyOn(globalThis, 'fetch');
    clearManifestCache();
    resetTpmjsClient();
  });

  afterEach(() => {
    fetchSpy.mockRestore();
  });

  describe('loadFetchConfig', () => {
    it('loads a valid fetch.config.json from explicit path', async () => {
      const tmpDir = await fs.mkdtemp(path.join(os.tmpdir(), 'tpmjs-test-'));
      const configPath = path.join(tmpDir, 'fetch.config.json');
      await fs.writeFile(configPath, JSON.stringify({ tools: ['@tpmjs/foo', 'bar-tool'] }));

      const config = await loadFetchConfig(configPath);
      expect(config.tools).toEqual(['@tpmjs/foo', 'bar-tool']);

      await fs.rm(tmpDir, { recursive: true });
    });

    it('returns empty tools array when no config file exists', async () => {
      const config = await loadFetchConfig('/nonexistent/path/fetch.config.json');
      expect(config.tools).toEqual([]);
    });

    it('returns empty tools array for invalid config', async () => {
      const tmpDir = await fs.mkdtemp(path.join(os.tmpdir(), 'tpmjs-test-'));
      const configPath = path.join(tmpDir, 'fetch.config.json');
      await fs.writeFile(configPath, 'not valid json{{{');

      const config = await loadFetchConfig(configPath);
      expect(config.tools).toEqual([]);

      await fs.rm(tmpDir, { recursive: true });
    });

    it('defaults tools to empty array when tools field is missing', async () => {
      const tmpDir = await fs.mkdtemp(path.join(os.tmpdir(), 'tpmjs-test-'));
      const configPath = path.join(tmpDir, 'fetch.config.json');
      await fs.writeFile(configPath, JSON.stringify({ other: 'field' }));

      const config = await loadFetchConfig(configPath);
      expect(config.tools).toEqual([]);

      await fs.rm(tmpDir, { recursive: true });
    });
  });

  describe('resolveTools', () => {
    const sseManifest: TpmjsManifest = {
      name: '@tpmjs/sse-tool',
      version: '1.0.0',
      description: 'An SSE tool',
      tools: [
        {
          name: 'sse_action',
          description: 'Do something via SSE',
          parameters: [
            { name: 'query', type: 'string', description: 'Search query', required: true },
          ],
        },
      ],
      mcp: {
        transport: 'sse',
        url: 'https://sse.example.com/mcp',
      },
    };

    const stdioManifest: TpmjsManifest = {
      name: '@tpmjs/stdio-tool',
      version: '2.0.0',
      description: 'A stdio tool',
      tools: [
        {
          name: 'stdio_action',
          description: 'Do something via stdio',
          parameters: [
            { name: 'input', type: 'string', description: 'Input text' },
            { name: 'count', type: 'number', description: 'How many', required: true },
            { name: 'verbose', type: 'boolean', description: 'Verbose mode' },
          ],
        },
      ],
      mcp: {
        transport: 'stdio',
        command: 'node',
        args: ['server.js'],
      },
      package: '@tpmjs/stdio-tool-server',
    };

    const noMcpManifest: TpmjsManifest = {
      name: 'no-mcp-tool',
      version: '1.0.0',
      description: 'No MCP config',
      tools: [
        {
          name: 'stub_action',
          description: 'A stub tool',
          parameters: [],
        },
      ],
    };

    it('returns empty array for empty package list', async () => {
      const tools = await resolveTools([]);
      expect(tools).toEqual([]);
    });

    it('resolves SSE manifest tools into OrchestratorTools', async () => {
      fetchSpy.mockResolvedValue(
        new Response(JSON.stringify(sseManifest), { status: 200 }),
      );

      const tools = await resolveTools(['@tpmjs/sse-tool']);
      expect(tools).toHaveLength(1);
      expect(tools[0].name).toBe('sse_action');
      expect(tools[0].description).toContain('[TPMJS: @tpmjs/sse-tool]');
      expect(tools[0].isCustom).toBe(true);
      expect(typeof tools[0].handler).toBe('function');
    });

    it('resolves stdio manifest tools into OrchestratorTools', async () => {
      // Mock manifest fetch + node_modules access check (not installed → install)
      fetchSpy.mockResolvedValue(
        new Response(JSON.stringify(stdioManifest), { status: 200 }),
      );

      const tools = await resolveTools(['@tpmjs/stdio-tool']);
      expect(tools).toHaveLength(1);
      expect(tools[0].name).toBe('stdio_action');
    });

    it('resolves tools without MCP config as stubs', async () => {
      fetchSpy.mockResolvedValue(
        new Response(JSON.stringify(noMcpManifest), { status: 200 }),
      );

      const tools = await resolveTools(['no-mcp-tool']);
      expect(tools).toHaveLength(1);

      // Execute the stub handler — should return failure
      const result = await tools[0].handler({});
      expect(result.success).toBe(false);
      expect(result.output).toContain('no MCP configuration');
    });

    it('caches manifests after resolution', async () => {
      fetchSpy.mockResolvedValue(
        new Response(JSON.stringify(sseManifest), { status: 200 }),
      );

      await resolveTools(['@tpmjs/sse-tool']);
      const cached = getCachedManifest('@tpmjs/sse-tool');
      expect(cached).toEqual(sseManifest);
    });

    it('skips packages that fail to fetch', async () => {
      fetchSpy.mockResolvedValue(new Response('', { status: 404 }));

      const tools = await resolveTools(['nonexistent-pkg']);
      expect(tools).toEqual([]);
    });

    it('resolves multiple packages', async () => {
      fetchSpy
        .mockResolvedValueOnce(new Response(JSON.stringify(sseManifest), { status: 200 }))
        .mockResolvedValueOnce(new Response(JSON.stringify(noMcpManifest), { status: 200 }));

      const tools = await resolveTools(['@tpmjs/sse-tool', 'no-mcp-tool']);
      expect(tools).toHaveLength(2);
      expect(tools.map(t => t.name)).toContain('sse_action');
      expect(tools.map(t => t.name)).toContain('stub_action');
    });
  });

  describe('resolveSinglePackage', () => {
    it('delegates to resolveTools with single-element array', async () => {
      fetchSpy.mockResolvedValue(
        new Response(JSON.stringify({
          name: 'test-pkg',
          version: '1.0.0',
          description: 'Test',
          tools: [{ name: 'test_tool', description: 'Test', parameters: [] }],
        }), { status: 200 }),
      );

      const tools = await resolveSinglePackage('test-pkg');
      expect(tools).toHaveLength(1);
      expect(tools[0].name).toBe('test_tool');
    });
  });

  describe('SSE/HTTP handler execution', () => {
    it('calls MCP endpoint and parses text content', async () => {
      const manifest: TpmjsManifest = {
        name: 'http-tool',
        version: '1.0.0',
        description: 'HTTP tool',
        tools: [{
          name: 'http_action',
          description: 'HTTP action',
          parameters: [{ name: 'q', type: 'string', description: 'query' }],
        }],
        mcp: { transport: 'streamable-http', url: 'https://mcp.example.com/rpc' },
      };

      // First call: manifest fetch; second call: MCP tool invocation
      fetchSpy
        .mockResolvedValueOnce(new Response(JSON.stringify(manifest), { status: 200 }))
        .mockResolvedValueOnce(new Response(JSON.stringify({
          result: { content: [{ type: 'text', text: 'Hello from MCP' }] },
        }), { status: 200 }));

      const tools = await resolveTools(['http-tool']);
      expect(tools).toHaveLength(1);

      const result = await tools[0].handler({ q: 'test' });
      expect(result.success).toBe(true);
      expect(result.output).toBe('Hello from MCP');
    });

    it('handles MCP error response', async () => {
      const manifest: TpmjsManifest = {
        name: 'err-tool',
        version: '1.0.0',
        description: 'Error tool',
        tools: [{
          name: 'err_action',
          description: 'Errors',
          parameters: [],
        }],
        mcp: { transport: 'sse', url: 'https://mcp.example.com/rpc' },
      };

      fetchSpy
        .mockResolvedValueOnce(new Response(JSON.stringify(manifest), { status: 200 }))
        .mockResolvedValueOnce(new Response(JSON.stringify({
          error: { message: 'Tool failed' },
        }), { status: 200 }));

      const tools = await resolveTools(['err-tool']);
      const result = await tools[0].handler({});
      expect(result.success).toBe(false);
      expect(result.output).toBe('Tool failed');
    });

    it('handles HTTP error status from MCP endpoint', async () => {
      const manifest: TpmjsManifest = {
        name: 'http-err',
        version: '1.0.0',
        description: 'HTTP error',
        tools: [{
          name: 'http_err_action',
          description: 'Errors',
          parameters: [],
        }],
        mcp: { transport: 'sse', url: 'https://mcp.example.com/rpc' },
      };

      fetchSpy
        .mockResolvedValueOnce(new Response(JSON.stringify(manifest), { status: 200 }))
        .mockResolvedValueOnce(new Response('Server Error', { status: 500 }));

      const tools = await resolveTools(['http-err']);
      const result = await tools[0].handler({});
      expect(result.success).toBe(false);
      expect(result.output).toContain('500');
    });

    it('returns error when SSE tool has no URL', async () => {
      const manifest: TpmjsManifest = {
        name: 'no-url',
        version: '1.0.0',
        description: 'No URL',
        tools: [{
          name: 'no_url_action',
          description: 'Missing URL',
          parameters: [],
        }],
        mcp: { transport: 'sse' },
      };

      fetchSpy.mockResolvedValueOnce(
        new Response(JSON.stringify(manifest), { status: 200 }),
      );

      const tools = await resolveTools(['no-url']);
      const result = await tools[0].handler({});
      expect(result.success).toBe(false);
      expect(result.output).toContain('requires a URL');
    });
  });

  describe('clearManifestCache', () => {
    it('clears the cache', async () => {
      const manifest: TpmjsManifest = {
        name: 'cached-pkg',
        version: '1.0.0',
        description: 'Cached',
        tools: [{ name: 'cached_tool', description: 'Test', parameters: [] }],
      };

      fetchSpy.mockResolvedValue(
        new Response(JSON.stringify(manifest), { status: 200 }),
      );

      await resolveTools(['cached-pkg']);
      expect(getCachedManifest('cached-pkg')).toBeDefined();

      clearManifestCache();
      expect(getCachedManifest('cached-pkg')).toBeUndefined();
    });
  });
});

